def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "pay_invoice": And([
            LT(self.settled_cash, 60),
            Not(self.settlement_confirmed)
        ]),
        "invest_funds": And([
            LT(self.settled_cash, 40),
            Not(self.settlement_confirmed)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
